1	import 'dart:async';
2	
3	import 'package:flutter_test/flutter_test.dart';
4	import 'package:fpdart/fpdart.dart';
5	import 'package:mocktail/mocktail.dart';
6	
7	import 'package:cerne/core/failure/failure.dart';
8	import 'package:cerne/features/account/data/datasources/account_remote_data_source.dart';
9	import 'package:cerne/features/account/data/models/account_settings_dto.dart';
10	import 'package:cerne/features/account/data/repositories/account_settings_repository_impl.dart';
11	
12	class MockAccountRemoteDataSource extends Mock
13	    implements AccountRemoteDataSource {}
14	
15	/// Covers spec-2-4's I/O & Edge-Case Matrix exactly:
16	/// - boot fetch resolves `false`/`true` -> `currentBiometricEnabled`/
17	///   `biometricEnabledStream` updated.
18	/// - boot fetch fails -> swallowed, `currentBiometricEnabled` unchanged.
19	/// - toggle succeeds -> flips immediately, persists, no error.
20	/// - toggle fails -> reverts to the prior value, `Left(Failure)` returned
21	///   so the caller can surface its message.
22	void main() {
23	  late MockAccountRemoteDataSource mockRemoteDataSource;
24	  late AccountSettingsRepositoryImpl repository;
25	
26	  setUp(() {
27	    mockRemoteDataSource = MockAccountRemoteDataSource();
28	    repository = AccountSettingsRepositoryImpl(
29	      remoteDataSource: mockRemoteDataSource,
30	    );
31	  });
32	
33	  tearDown(() => repository.dispose());
34	
35	  /// Same rationale as `vault_repository_impl_test.dart`'s own
36	  /// `emittedDuring` helper: `biometricEnabledStream` always synchronously
37	  /// replays the current value to a brand-new listener, so that replay is
38	  /// drained and discarded here first.
39	  Future<List<bool>> emittedDuring(Future<void> Function() act) async {
40	    final emitted = <bool>[];
41	    final subscription = repository.biometricEnabledStream.listen(emitted.add);
42	    await Future<void>.delayed(Duration.zero);
43	    emitted.clear();
44	    await act();
45	    await Future<void>.delayed(Duration.zero);
46	    await subscription.cancel();
47	    return emitted;
48	  }
49	
50	  group('currentBiometricEnabled — starts true, never null (Boundaries)', () {
51	    test('currentBiometricEnabled is true before any fetch/toggle call', () {
52	      expect(repository.currentBiometricEnabled, isTrue);
53	    });
54	
55	    test('a listener that subscribes before any call still immediately '
56	        'sees true, not nothing until the first emission (Stream.multi '
57	        'replay)', () async {
