288	
289	      expect(firstResult.isLeft(), isTrue);
290	      // The second call's confirmed value must still be in effect,
291	      // untouched by the first (superseded) call's own resolution.
292	      expect(repository.currentBiometricEnabled, isTrue);
293	    });
294	  });
