10	/// A plain (non-mocktail) fake — same rationale as `vault_lock_screen_test.
11	/// dart`'s own `_FakeVaultRepository`: this suite needs a scriptable
12	/// `setBiometricEnabled()` result plus a real stream the cubit actually
13	/// subscribes to, which a mocktail stub can't give as naturally.
14	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
15	  bool _value = true;
16	  final _controller = StreamController<bool>.broadcast();
17	
18	  /// The next `setBiometricEnabled()` call's own result — defaults to a
19	  /// failure so a test must opt in to the success path explicitly.
20	  Either<Failure, Unit> setBiometricEnabledResult = left(
21	    const Failure.malformedResponse(message: 'fake: not configured'),
22	  );
23	
24	  int setBiometricEnabledCallCount = 0;
25	
26	  @override
27	  bool get currentBiometricEnabled => _value;
28	
29	  @override
30	  Stream<bool> get biometricEnabledStream {
31	    return Stream<bool>.multi((controller) {
32	      controller.add(_value);
33	      final subscription = _controller.stream.listen(
34	        controller.add,
35	        onError: controller.addError,
36	        onDone: controller.close,
37	      );
38	      controller.onCancel = subscription.cancel;
39	    }, isBroadcast: true);
40	  }
41	
42	  @override
43	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
44	
45	  @override
46	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
47	    setBiometricEnabledCallCount += 1;
48	    final previous = _value;
49	    _emit(enabled);
50	    final result = setBiometricEnabledResult;
51	    if (result.isLeft()) {
52	      _emit(previous);
53	    }
54	    return result;
55	  }
56	
57	  @override
58	  Future<void> dispose() => _controller.close();
59	
60	  void _emit(bool value) {
61	    _value = value;
62	    _controller.add(value);
63	  }
64	}
65	
66	Future<List<AccountSettingsState>> _emittedDuring(
67	  AccountSettingsCubit cubit,
68	  Future<void> Function() act,
69	) async {
70	  final emitted = <AccountSettingsState>[];
71	  final subscription = cubit.stream.listen(emitted.add);
72	  await act();
73	  // `pumpEventQueue()` (not a single `Future.delayed(Duration.zero)`): the
74	  // `biometricEnabled` mirror travels repository -> Stream.multi's own
75	  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
76	  // several microtask hops deep — one `Duration.zero` delay only guarantees
77	  // draining one hop, leaving a later hop's delivery to land after this
78	  // helper already returned.
79	  await pumpEventQueue();
80	  await subscription.cancel();
81	  return emitted;
82	}
83	
84	void main() {
85	  late _FakeAccountSettingsRepository fakeRepository;
86	
87	  setUp(() {
88	    fakeRepository = _FakeAccountSettingsRepository();
89	  });
90	
91	  group('initial state', () {
92	    test('mirrors currentBiometricEnabled (true) at construction', () async {
93	      final cubit = AccountSettingsCubit(fakeRepository);
94	
95	      expect(cubit.state.biometricEnabled, isTrue);
96	      expect(cubit.state.errorMessage, isNull);
97	      await cubit.close();
98	    });
99	
100	    test('mirrors a false currentBiometricEnabled (e.g. already fetched '
101	        'before the screen opened)', () async {
102	      fakeRepository._emit(false);
103	      final cubit = AccountSettingsCubit(fakeRepository);
104	
105	      expect(cubit.state.biometricEnabled, isFalse);
106	      await cubit.close();
107	    });
108	  });
109	
110	  group('toggleBiometric() — success', () {
111	    test('flips to the new value and clears any prior error, calling the '
112	        'repository with exactly the requested value', () async {
113	      fakeRepository.setBiometricEnabledResult = right(unit);
114	      final cubit = AccountSettingsCubit(fakeRepository);
115	
116	      final emitted = await _emittedDuring(
117	        cubit,
118	        () => cubit.toggleBiometric(false),
119	      );
120	
121	      expect(emitted.last.biometricEnabled, isFalse);
122	      expect(emitted.last.errorMessage, isNull);
123	      expect(fakeRepository.setBiometricEnabledCallCount, 1);
124	      await cubit.close();
125	    });
126	  });
127	
128	  group('toggleBiometric() — failure', () {
129	    test('the switch reverts (mirrored from the repository\'s own revert) '
130	        'and the Failure\'s message is surfaced', () async {
131	      fakeRepository.setBiometricEnabledResult = left(
132	        const Failure.networkTimeout(message: 'Sem conexão'),
133	      );
134	      final cubit = AccountSettingsCubit(fakeRepository);
135	      // Drains the constructor's own subscription-replay of the current
136	      // value (Stream.multi's replay goes through its own forwarding
137	      // subscription, several microtask hops deep) before the capture
138	      // window below starts — otherwise that replay (allowed through by
139	      // Cubit's own "first emit always goes through" rule) can land
140	      // mid-capture as a spurious extra entry. `pumpEventQueue()` drains
141	      // repeatedly until the queue is empty, rather than a single
142	      // `Future.delayed(Duration.zero)` which only guarantees one hop.
143	      await pumpEventQueue();
144	
145	      final emitted = await _emittedDuring(
146	        cubit,
147	        () => cubit.toggleBiometric(false),
148	      );
149	
150	      // Two independent emission paths feed `emitted` here: the
151	      // `biometricEnabled` flip/revert mirrors the repository's own stream
152	      // (several `Stream.multi` forwarding hops deep), while the
153	      // `errorMessage` update is `toggleBiometric()`'s own direct `emit()`
154	      // (one hop). Their relative *order* isn't guaranteed by either path's
155	      // own contract, so asserting an exact sequence would pin an
156	      // implementation accident, not a behavior the spec requires — what
157	      // the I/O matrix actually requires (and what's asserted below) is
158	      // that the optimistic flip to `false` was visible at some point, and
159	      // that the settled end state reverted to `true` with the `Failure`'s
160	      // message surfaced.
161	      expect(emitted.map((s) => s.biometricEnabled), contains(false));
162	      expect(emitted.last.biometricEnabled, isTrue);
163	      expect(emitted.last.errorMessage, 'Sem conexão');
164	      expect(cubit.state.biometricEnabled, isTrue);
165	      expect(cubit.state.errorMessage, 'Sem conexão');
166	      await cubit.close();
167	    });
168	
169	    test(
170	      'a later successful toggle clears the previous error message',
171	      () async {
172	        fakeRepository.setBiometricEnabledResult = left(
173	          const Failure.networkTimeout(message: 'Sem conexão'),
174	        );
175	        final cubit = AccountSettingsCubit(fakeRepository);
176	        await cubit.toggleBiometric(false);
177	        // `toggleBiometric()`'s own await only guarantees its direct
178	        // `setBiometricEnabled()` Future resolved — the `biometricEnabled`
179	        // mirror it emits travels back through the repository's
180	        // `Stream.multi` forwarding subscription, several microtask hops
181	        // behind that Future; drain those before asserting on `cubit.state`
182	        // (same rationale as `_emittedDuring`'s own `pumpEventQueue()`).
183	        await pumpEventQueue();
184	        expect(cubit.state.errorMessage, 'Sem conexão');
185	
186	        fakeRepository.setBiometricEnabledResult = right(unit);
187	        await cubit.toggleBiometric(true);
188	        await pumpEventQueue();
189	
190	        expect(cubit.state.errorMessage, isNull);
191	        expect(cubit.state.biometricEnabled, isTrue);
192	        await cubit.close();
193	      },
194	    );
195	  });
196	}
