193	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
194	/// pair and pumps the real screen around it, registering both for cleanup.
195	///
196	/// Deliberately constructed *inside* each `testWidgets` body (via this
197	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
198	/// `package:test`'s own per-test zone, a different zone than the one
199	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
200	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
201	/// subscription to the repository's stream, set up in its constructor)
202	/// created in that outer zone does not reliably get its pending events
203	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
204	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
205	/// widget never rebuilt, no matter how many `pump()` calls followed.
206	/// Constructing the cubit here, inside the same zone `tester.pump()`
207	/// drains, avoids the mismatch entirely.
208	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
209	  WidgetTester tester,
210	) async {
211	  final fakeRepository = _FakeAccountSettingsRepository();
212	  final cubit = AccountSettingsCubit(fakeRepository);
213	  addTearDown(() => cubit.close());
214	  addTearDown(fakeRepository.dispose);
215	
216	  final router = _routerWith(
217	    AccountSettingsScreen(
218	      cubit: cubit,
219	      dashboardCubit: _buildDashboardCubit(),
220	      narrativeCubit: _buildNarrativeCubit(),
221	    ),
222	  );
223	  addTearDown(router.dispose);
224	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
225	
226	  return (fakeRepository, cubit);
227	}
