279	    }, (_) {
280	      emit(
281	        state.copyWith(
282	          isEditingName: false,
283	          isSavingName: false,
284	          displayName: trimmed,
285	          clearNameErrorMessage: true,
286	        ),
287	      );
288	    });
289	  }
