10	/// A plain (non-mocktail) fake — same rationale as `vault_lock_screen_test.
11	/// dart`'s own `_FakeVaultRepository`: this suite needs a scriptable
12	/// `setBiometricEnabled()` result plus a real stream the cubit actually
13	/// subscribes to, which a mocktail stub can't give as naturally.
14	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
15	  bool _value = true;
16	  final _controller = StreamController<bool>.broadcast();
17	
18	  /// The next `setBiometricEnabled()` call's own result — defaults to a
19	  /// failure so a test must opt in to the success path explicitly.
20	  Either<Failure, Unit> setBiometricEnabledResult = left(
21	    const Failure.malformedResponse(message: 'fake: not configured'),
22	  );
23	
24	  int setBiometricEnabledCallCount = 0;
25	
26	  // spec-8-3 — a scriptable profile-name slice, same rationale
27	  // [setBiometricEnabledResult] already gives for the toggle: a test must
28	  // opt in to a non-default [currentDisplayName]/[currentEmail] or a
29	  // [setDisplayNameResult] success explicitly.
30	  @override
31	  String currentDisplayName = '';
32	  @override
33	  String currentEmail = '';
34	  Either<Failure, Unit> setDisplayNameResult = left(
35	    const Failure.malformedResponse(message: 'fake: not configured'),
36	  );
37	  int setDisplayNameCallCount = 0;
38	  String? lastSetDisplayNameArg;
39	
40	  @override
41	  Future<Either<Failure, Unit>> setDisplayName(String name) async {
42	    setDisplayNameCallCount += 1;
43	    lastSetDisplayNameArg = name;
44	    return setDisplayNameResult;
45	  }
46	
47	  @override
48	  bool get currentBiometricEnabled => _value;
49	
50	  @override
51	  Stream<bool> get biometricEnabledStream {
52	    return Stream<bool>.multi((controller) {
53	      controller.add(_value);
54	      final subscription = _controller.stream.listen(
55	        controller.add,
56	        onError: controller.addError,
57	        onDone: controller.close,
58	      );
59	      controller.onCancel = subscription.cancel;
60	    }, isBroadcast: true);
61	  }
62	
63	  @override
64	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
65	
66	  @override
67	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
68	    setBiometricEnabledCallCount += 1;
69	    final previous = _value;
70	    _emit(enabled);
71	    final result = setBiometricEnabledResult;
72	    if (result.isLeft()) {
73	      _emit(previous);
74	    }
75	    return result;
76	  }
77	
78	  @override
79	  Future<void> dispose() => _controller.close();
80	
81	  void _emit(bool value) {
82	    _value = value;
83	    _controller.add(value);
84	  }
85	}
86	
87	Future<List<AccountSettingsState>> _emittedDuring(
88	  AccountSettingsCubit cubit,
89	  Future<void> Function() act,
90	) async {
91	  final emitted = <AccountSettingsState>[];
92	  final subscription = cubit.stream.listen(emitted.add);
93	  await act();
94	  // `pumpEventQueue()` (not a single `Future.delayed(Duration.zero)`): the
95	  // `biometricEnabled` mirror travels repository -> Stream.multi's own
96	  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
97	  // several microtask hops deep — one `Duration.zero` delay only guarantees
98	  // draining one hop, leaving a later hop's delivery to land after this
99	  // helper already returned.
100	  await pumpEventQueue();
101	  await subscription.cancel();
102	  return emitted;
103	}
104	
105	void main() {
106	  late _FakeAccountSettingsRepository fakeRepository;
107	
108	  setUp(() {
109	    fakeRepository = _FakeAccountSettingsRepository();
110	  });
111	
112	  group('initial state', () {
113	    test('mirrors currentBiometricEnabled (true) at construction', () async {
114	      final cubit = AccountSettingsCubit(fakeRepository);
115	
116	      expect(cubit.state.biometricEnabled, isTrue);
117	      expect(cubit.state.errorMessage, isNull);
118	      await cubit.close();
119	    });
120	
121	    test('mirrors a false currentBiometricEnabled (e.g. already fetched '
122	        'before the screen opened)', () async {
123	      fakeRepository._emit(false);
124	      final cubit = AccountSettingsCubit(fakeRepository);
125	
126	      expect(cubit.state.biometricEnabled, isFalse);
127	      await cubit.close();
128	    });
129	  });
130	
131	  group('toggleBiometric() — success', () {
132	    test('flips to the new value and clears any prior error, calling the '
133	        'repository with exactly the requested value', () async {
134	      fakeRepository.setBiometricEnabledResult = right(unit);
135	      final cubit = AccountSettingsCubit(fakeRepository);
136	
137	      final emitted = await _emittedDuring(
138	        cubit,
139	        () => cubit.toggleBiometric(false),
140	      );
141	
142	      expect(emitted.last.biometricEnabled, isFalse);
143	      expect(emitted.last.errorMessage, isNull);
144	      expect(fakeRepository.setBiometricEnabledCallCount, 1);
145	      await cubit.close();
146	    });
147	  });
148	
149	  group('toggleBiometric() — failure', () {
150	    test('the switch reverts (mirrored from the repository\'s own revert) '
151	        'and the Failure\'s message is surfaced', () async {
152	      fakeRepository.setBiometricEnabledResult = left(
153	        const Failure.networkTimeout(message: 'Sem conexão'),
154	      );
155	      final cubit = AccountSettingsCubit(fakeRepository);
156	      // Drains the constructor's own subscription-replay of the current
157	      // value (Stream.multi's replay goes through its own forwarding
158	      // subscription, several microtask hops deep) before the capture
159	      // window below starts — otherwise that replay (allowed through by
160	      // Cubit's own "first emit always goes through" rule) can land
161	      // mid-capture as a spurious extra entry. `pumpEventQueue()` drains
162	      // repeatedly until the queue is empty, rather than a single
163	      // `Future.delayed(Duration.zero)` which only guarantees one hop.
164	      await pumpEventQueue();
165	
166	      final emitted = await _emittedDuring(
167	        cubit,
168	        () => cubit.toggleBiometric(false),
169	      );
170	
171	      // Two independent emission paths feed `emitted` here: the
172	      // `biometricEnabled` flip/revert mirrors the repository's own stream
173	      // (several `Stream.multi` forwarding hops deep), while the
174	      // `errorMessage` update is `toggleBiometric()`'s own direct `emit()`
175	      // (one hop). Their relative *order* isn't guaranteed by either path's
176	      // own contract, so asserting an exact sequence would pin an
177	      // implementation accident, not a behavior the spec requires — what
178	      // the I/O matrix actually requires (and what's asserted below) is
179	      // that the optimistic flip to `false` was visible at some point, and
180	      // that the settled end state reverted to `true` with the `Failure`'s
181	      // message surfaced.
182	      expect(emitted.map((s) => s.biometricEnabled), contains(false));
183	      expect(emitted.last.biometricEnabled, isTrue);
184	      expect(emitted.last.errorMessage, 'Sem conexão');
185	      expect(cubit.state.biometricEnabled, isTrue);
186	      expect(cubit.state.errorMessage, 'Sem conexão');
187	      await cubit.close();
188	    });
189	
190	    test(
191	      'a later successful toggle clears the previous error message',
192	      () async {
193	        fakeRepository.setBiometricEnabledResult = left(
194	          const Failure.networkTimeout(message: 'Sem conexão'),
195	        );
196	        final cubit = AccountSettingsCubit(fakeRepository);
197	        await cubit.toggleBiometric(false);
198	        // `toggleBiometric()`'s own await only guarantees its direct
199	        // `setBiometricEnabled()` Future resolved — the `biometricEnabled`
200	        // mirror it emits travels back through the repository's
201	        // `Stream.multi` forwarding subscription, several microtask hops
202	        // behind that Future; drain those before asserting on `cubit.state`
203	        // (same rationale as `_emittedDuring`'s own `pumpEventQueue()`).
204	        await pumpEventQueue();
205	        expect(cubit.state.errorMessage, 'Sem conexão');
206	
207	        fakeRepository.setBiometricEnabledResult = right(unit);
208	        await cubit.toggleBiometric(true);
209	        await pumpEventQueue();
210	
211	        expect(cubit.state.errorMessage, isNull);
212	        expect(cubit.state.biometricEnabled, isTrue);
213	        await cubit.close();
214	      },
215	    );
216	  });
217	}
